FILES = {'judge.py': '"""judge.py - the data and the reference scoring code. The agent may NOT edit this file or the data it reads.\n\nData (all wikitext-103, disjoint by source file and by article):\n    search      validation-split articles, even-numbered   (the agent\'s reward; split into rotating subsets)\n    validation  validation-split articles, odd-numbered    (gate before an architecture can become the saved best)\n    test        test split                                 (final report only)\n    calib       train split, first articles                (usage statistics: which neurons are most used)\nperplexity() / speed() here run the HuggingFace model and are the reference that smol.py and fastgen.py are\ntested against (test_exact.py).\n"""\nimport os, re, time, statistics, functools\nimport numpy as np, torch, pandas as pd\n\nROOT = os.environ.get(\'PRUNE_ROOT\', \'/tmp/claude-0/-home-user-Eco-1-0/44fe88f8-9d28-5d7b-9454-d407264e70f1/scratchpad/prune\')\nMODEL_DIR = f\'{ROOT}/model\'\nDATA = f\'{ROOT}/data/wikitext-103-raw-v1\'\nSEQ = int(os.environ.get(\'SEQ\', 256))\nSIZES = {\'search\': int(os.environ.get(\'SEARCH_N\', 128)), \'validation\': int(os.environ.get(\'VAL_N\', 128)),\n         \'test\': int(os.environ.get(\'TEST_N\', 256)), \'calib\': int(os.environ.get(\'CALIB_N\', 32))}\nDEVICE = os.environ.get(\'DEVICE\', \'cuda\' if torch.cuda.is_available() else \'cpu\')\nTHREADS = 3                     # 4 threads on this VM are noisy (one straggler vCPU stalls every matmul)\ntorch.set_num_threads(THREADS)\n\ndef _articles(path):\n    arts, cur = [], []\n    for row in pd.read_parquet(path)[\'text\'].tolist():\n        if row.startswith(\' = \') and not row.startswith(\' = = \') and cur:\n            arts.append(\'\'.join(cur)); cur = []\n        cur.append(row)\n    if cur: arts.append(\'\'.join(cur))\n    return [a for a in arts if len(a) > 2000]\n\n@functools.lru_cache(None)\ndef tokenizer():\n    from transformers import AutoTokenizer\n    return AutoTokenizer.from_pretrained(MODEL_DIR)\n\ndef _chunks(articles, n):\n    tok = tokenizer(); out = []\n    for a in articles:\n        ids = tok(a)[\'input_ids\']\n        for i in range(0, len(ids) - SEQ, SEQ):\n            out.append(ids[i:i + SEQ])\n            if len(out) == n: return torch.tensor(out)\n    raise RuntimeError(\'not enough text\')\n\n@functools.lru_cache(None)\ndef split(name):\n    if name in (\'search\', \'validation\'):\n        arts = _articles(f\'{DATA}/validation-00000-of-00001.parquet\')\n        arts = arts[0::2] if name == \'search\' else arts[1::2]\n        rng = np.random.default_rng(1); rng.shuffle(arts)\n        return _chunks(arts, SIZES[name])\n    if name == \'test\':\n        arts = _articles(f\'{DATA}/test-00000-of-00001.parquet\')\n        rng = np.random.default_rng(2); rng.shuffle(arts)\n        return _chunks(arts, SIZES[\'test\'])\n    if name == \'calib\':                                   # usage statistics only; from the train split\n        return _chunks(_articles(f\'{DATA}/train-00000-of-00002.parquet\')[:400], SIZES[\'calib\'])\n    raise KeyError(name)\n\n@torch.no_grad()\ndef perplexity(model, name, batch=16):\n    x = split(name); nll, n = 0.0, 0\n    model.eval()\n    for i in range(0, len(x), batch):\n        b = x[i:i + batch].to(DEVICE)\n        logits = model(b).logits[:, :-1].float()\n        loss = torch.nn.functional.cross_entropy(logits.reshape(-1, logits.size(-1)), b[:, 1:].reshape(-1), reduction=\'sum\')\n        nll += loss.item(); n += b[:, 1:].numel()\n    return float(np.exp(nll / n))\n\nPROMPTS = [\'The history of the city began in\', \'In 1998, the band released\', \'The species is found in\', \'During the war, the army\']\n\n@torch.no_grad()\ndef speed(model, runs=20, new_tokens=64, warmup=2):\n    """Median tokens/second for greedy generation (batch 1, KV cache). On GPU: CUDA-graph decoder."""\n    if DEVICE == \'cuda\':\n        r = [gpu_speed(model, runs=3, new_tokens=new_tokens) for _ in range(max(3, runs // 4))]\n        return statistics.median(r), statistics.stdev(r) / len(r) ** 0.5\n    tok = tokenizer(); model.eval(); rates = []\n    for r in range(warmup + runs):\n        ids = tok(PROMPTS[r % len(PROMPTS)], return_tensors=\'pt\')[\'input_ids\'].to(DEVICE); _sync()\n        t0 = time.perf_counter()\n        model.generate(ids, max_new_tokens=new_tokens, min_new_tokens=new_tokens, do_sample=False, pad_token_id=0)\n        _sync(); dt = time.perf_counter() - t0\n        if r >= warmup: rates.append(new_tokens / dt)\n    return statistics.median(rates), statistics.stdev(rates) / len(rates) ** 0.5\n\ndef _sync():\n    if DEVICE == \'cuda\': torch.cuda.synchronize()\n\ndef load_original():\n    from transformers import AutoModelForCausalLM\n    return AutoModelForCausalLM.from_pretrained(MODEL_DIR, dtype=torch.float32).to(DEVICE)\n\n@torch.no_grad()\ndef sample(model, prompt, n=40):\n    tok = tokenizer(); ids = tok(prompt, return_tensors=\'pt\')[\'input_ids\'].to(DEVICE)\n    out = model.generate(ids, max_new_tokens=n, do_sample=False, pad_token_id=0)\n    return tok.decode(out[0][ids.shape[1]:])\n\n@torch.no_grad()\ndef quick_speed(model, runs=6, new_tokens=48):\n    """Fast, low-noise speed reading for per-step rewards: same prompt every run, best (minimum) time of N."""\n    if DEVICE == \'cuda\': return gpu_speed(model, runs=runs, new_tokens=64)\n    tok = tokenizer(); model.eval(); ids = tok(PROMPTS[0], return_tensors=\'pt\')[\'input_ids\'].to(DEVICE)\n    model.generate(ids, max_new_tokens=8, do_sample=False, pad_token_id=0)            # warm-up\n    best = 1e9\n    for _ in range(runs):\n        _sync(); t0 = time.perf_counter()\n        model.generate(ids, max_new_tokens=new_tokens, min_new_tokens=new_tokens, do_sample=False, pad_token_id=0)\n        _sync(); best = min(best, time.perf_counter() - t0)\n    return new_tokens / best\n\n\n@torch.no_grad()\ndef gpu_speed(model, runs=5, new_tokens=64):\n    """GPU tokens/second with the CUDA-graph decoder (fastgen.py): best of N, same prompt."""\n    import fastgen\n    g = fastgen.FastGen(model, max_len=128); g.capture()\n    ids = tokenizer()(PROMPTS[0])[\'input_ids\']; best = 1e9\n    for _ in range(runs + 1):\n        g._reset(ids); _sync(); t0 = time.perf_counter(); g.decode(new_tokens); _sync()\n        best = min(best, time.perf_counter() - t0)\n    return new_tokens / best\n', 'smol.py': '"""smol.py - SmolLM-135M as plain tensors, plus an architecture description (Arch) of what is kept.\n\nAn Arch never changes a weight. It only says, for every layer:\n    attn[i]   keep the attention sublayer?\n    kv[i]     which key/value head groups are kept (bitmask; each group carries its 3 query heads)\n    w[i]      MLP width as an index into WIDTHS (most-used neurons are kept); -1 = MLP sublayer removed\nand, for the whole model:\n    half      run the weights in 16-bit floats instead of 32-bit\n\nNet.layer / Net.nll evaluate any Arch exactly (removed parts are masked or skipped), so the perplexity of an\nedited model costs one forward pass and no model surgery. materialize() builds the physically smaller weights\nthat the decoder (fastgen.py) runs, which is what speed is measured on.\n"""\nimport math, torch, torch.nn.functional as F\n\nWIDTHS = [1.0, 0.9, 0.8, 0.7, 0.6, 0.5, 0.4, 0.3]\n\n\ndef extract(hf):\n    """Pull the weights out of a HuggingFace LlamaForCausalLM (fp32, CPU)."""\n    c = hf.config\n    theta = getattr(c, \'rope_theta\', None) or (getattr(c, \'rope_parameters\', None) or {}).get(\'rope_theta\', 10000.0)\n    assert hf.lm_head.weight is hf.model.embed_tokens.weight or torch.equal(hf.lm_head.weight, hf.model.embed_tokens.weight)\n    P = dict(E=hf.model.embed_tokens.weight.detach().float().cpu(), nf=hf.model.norm.weight.detach().float().cpu(),\n             eps=c.rms_norm_eps, theta=theta, nq=c.num_attention_heads, nkv=c.num_key_value_heads,\n             hd=c.hidden_size // c.num_attention_heads, layers=[])\n    for l in hf.model.layers:\n        a, m = l.self_attn, l.mlp\n        P[\'layers\'].append({k: v.weight.detach().float().cpu() for k, v in dict(\n            n1=l.input_layernorm, n2=l.post_attention_layernorm, q=a.q_proj, k=a.k_proj, v=a.v_proj, o=a.o_proj,\n            g=m.gate_proj, u=m.up_proj, dn=m.down_proj).items()})\n    return P\n\n\nclass Arch:\n    __slots__ = (\'attn\', \'kv\', \'w\', \'half\')\n\n    def __init__(self, nl, nkv):\n        self.attn = [True] * nl; self.kv = [(1 << nkv) - 1] * nl; self.w = [0] * nl; self.half = False\n\n    def copy(self):\n        a = Arch.__new__(Arch); a.attn = list(self.attn); a.kv = list(self.kv); a.w = list(self.w); a.half = self.half\n        return a\n\n    def key(self):                       # perplexity does not depend on `half` during the search\n        return (tuple(self.attn), tuple(self.kv), tuple(self.w))\n\n    def apply(self, e):\n        a = self.copy(); k = e[0]\n        if k == \'attn\': a.attn[e[1]] = False\n        elif k == \'kv\': a.kv[e[1]] &= ~(1 << e[2])\n        elif k == \'p10\': a.w[e[1]] += 1\n        elif k == \'p30\': a.w[e[1]] += 3\n        elif k == \'mlp\': a.w[e[1]] = -1\n        elif k == \'half\': a.half = True\n        else: raise ValueError(e)\n        return a\n\n    def describe(self, nkv=3):\n        nl = len(self.attn); gone = lambda bits: [g for g in range(nkv) if not bits >> g & 1]\n        return dict(precision=\'fp16\' if self.half else \'fp32\',\n                    attention_removed=[i for i in range(nl) if not self.attn[i]],\n                    mlp_removed=[i for i in range(nl) if self.w[i] < 0],\n                    kv_groups_removed={str(i): gone(self.kv[i]) for i in range(nl) if self.attn[i] and gone(self.kv[i])},\n                    mlp_width={str(i): WIDTHS[self.w[i]] for i in range(nl) if self.w[i] > 0},\n                    attn=list(self.attn), kv=list(self.kv), w=list(self.w))\n\n    @staticmethod\n    def from_lists(attn, kv, w, half):\n        a = Arch.__new__(Arch); a.attn = list(attn); a.kv = list(kv); a.w = list(w); a.half = bool(half); return a\n\n\nclass Net:\n    """The model\'s tensors on one device in one precision. Never modified after construction."""\n\n    def __init__(self, P, device, half=False, T=256):\n        self.dev = torch.device(device); self.dt = torch.float16 if half else torch.float32\n        mv = lambda t: t.to(device=self.dev, dtype=self.dt)\n        self.E, self.nf = mv(P[\'E\']), mv(P[\'nf\'])\n        self.L = [{k: mv(v) for k, v in l.items()} for l in P[\'layers\']]\n        self.eps, self.nq, self.nkv, self.hd, self.theta = P[\'eps\'], P[\'nq\'], P[\'nkv\'], P[\'hd\'], P[\'theta\']\n        self.rep = self.nq // self.nkv; self.NL = len(self.L); self.dff = self.L[0][\'g\'].shape[0]\n        inv = 1.0 / (P[\'theta\'] ** (torch.arange(0, self.hd, 2, dtype=torch.float32) / self.hd))\n        fr = torch.outer(torch.arange(T, dtype=torch.float32), inv); emb = torch.cat([fr, fr], -1)\n        self.cos, self.sin = mv(emb.cos()), mv(emb.sin())\n        self.rank = None; self._nm = {}; self._hm = {}\n\n    def full(self): return Arch(self.NL, self.nkv)\n\n    def set_rank(self, rank): self.rank = [r.to(self.dev) for r in rank]; self._nm = {}\n\n    def nmask(self, i, widx):\n        m = self._nm.get((i, widx))\n        if m is None:\n            m = torch.zeros(self.dff, device=self.dev, dtype=self.dt)\n            m[self.rank[i][:round(self.dff * WIDTHS[widx])]] = 1; self._nm[(i, widx)] = m\n        return m\n\n    def hmask(self, bits):\n        m = self._hm.get(bits)\n        if m is None:\n            m = torch.tensor([float(bits >> (h // self.rep) & 1) for h in range(self.nq)], device=self.dev, dtype=self.dt).view(1, self.nq, 1, 1)\n            self._hm[bits] = m\n        return m\n\n    def norm(self, x, w):\n        return x * torch.rsqrt(x.float().pow(2).mean(-1, keepdim=True) + self.eps).to(x.dtype) * w\n\n    def rope(self, x):\n        T = x.shape[-2]; c, s = self.cos[:T], self.sin[:T]; h = x.shape[-1] // 2\n        return x * c + torch.cat([-x[..., h:], x[..., :h]], -1) * s\n\n    def attn_heads(self, p, x):\n        """Per-head attention outputs (B, nq, T, hd), before the output projection."""\n        h = self.norm(x, p[\'n1\']); B, T, _ = h.shape\n        q = (h @ p[\'q\'].T).view(B, T, self.nq, self.hd).transpose(1, 2)\n        k = (h @ p[\'k\'].T).view(B, T, self.nkv, self.hd).transpose(1, 2)\n        v = (h @ p[\'v\'].T).view(B, T, self.nkv, self.hd).transpose(1, 2)\n        q, k = self.rope(q), self.rope(k)\n        k, v = k.repeat_interleave(self.rep, 1), v.repeat_interleave(self.rep, 1)\n        return F.scaled_dot_product_attention(q, k, v, is_causal=True)\n\n    def layer(self, i, x, arch):\n        p = self.L[i]\n        if arch.attn[i]:\n            o = self.attn_heads(p, x); B, _, T, _ = o.shape\n            if arch.kv[i] != (1 << self.nkv) - 1: o = o * self.hmask(arch.kv[i])\n            x = x + o.transpose(1, 2).reshape(B, T, self.nq * self.hd) @ p[\'o\'].T\n        if arch.w[i] >= 0:\n            h = self.norm(x, p[\'n2\'])\n            a = F.silu(h @ p[\'g\'].T) * (h @ p[\'u\'].T)\n            if arch.w[i] > 0: a = a * self.nmask(i, arch.w[i])\n            x = x + a @ p[\'dn\'].T\n        return x\n\n    def embed(self, ids): return self.E[ids]\n\n    def logits(self, x): return self.norm(x, self.nf) @ self.E.T\n\n    def nll(self, x, ids, chunk=8):\n        """Per-sequence summed next-token negative log-likelihood (float32), from the final residual stream."""\n        out = []\n        for c in range(0, x.shape[0], chunk):\n            lg = self.logits(x[c:c + chunk, :-1]).float()\n            out.append((torch.logsumexp(lg, -1) - lg.gather(-1, ids[c:c + chunk, 1:, None]).squeeze(-1)).sum(1))\n        return torch.cat(out)\n\n    def seq_nll(self, ids, arch, batch=16):\n        """Full forward pass of an architecture: per-sequence NLL."""\n        out = []\n        for b in range(0, ids.shape[0], batch):\n            x = self.embed(ids[b:b + batch])\n            for i in range(self.NL): x = self.layer(i, x, arch)\n            out.append(self.nll(x, ids[b:b + batch]))\n        return torch.cat(out)\n\n    @torch.no_grad()\n    def stats(self, ids, batch=8):\n        """Usage statistics of every part of the original model on calibration text (not search/validation/test).\n        imp[i]   per-neuron importance: mean |activation| x norm of its output weights   (to keep the most-used)\n        aw[i]    how much the attention sublayer writes, relative to the residual stream (ratio of RMS)\n        kw[i][g] the same for each key/value head group\n        mw[i]    the same for the MLP sublayer\n        """\n        NL = self.NL; arch = self.full(); n = 0\n        imp = [torch.zeros(self.dff, device=self.dev) for _ in range(NL)]\n        aw = torch.zeros(NL); mw = torch.zeros(NL); kw = torch.zeros(NL, self.nkv)\n        rms = lambda t: t.float().pow(2).mean(-1).sqrt()\n        for b in range(0, ids.shape[0], batch):\n            x = self.embed(ids[b:b + batch]); B, T, _ = x.shape; n += 1\n            for i in range(NL):\n                p = self.L[i]\n                o = self.attn_heads(p, x)\n                xr = _robust_rms(x)\n                for g in range(self.nkv):\n                    og = (o * self.hmask(1 << g)).transpose(1, 2).reshape(B, T, -1) @ p[\'o\'].T\n                    kw[i, g] += (rms(og) / xr).mean().item()\n                ao = o.transpose(1, 2).reshape(B, T, -1) @ p[\'o\'].T\n                aw[i] += (rms(ao) / xr).mean().item(); x = x + ao\n                h = self.norm(x, p[\'n2\']); a = F.silu(h @ p[\'g\'].T) * (h @ p[\'u\'].T)\n                imp[i] += a.float().abs().mean(dim=(0, 1))\n                mo = a @ p[\'dn\'].T; mw[i] += (rms(mo) / _robust_rms(x)).mean().item(); x = x + mo\n        imp = [(v / n * self.L[i][\'dn\'].float().norm(dim=0)).cpu() for i, v in enumerate(imp)]\n        return dict(imp=imp, aw=aw / n, kw=kw / n, mw=mw / n)\n\n\ndef _robust_rms(x, drop=4):\n    """RMS of the residual stream ignoring its few huge-magnitude dimensions (they would swamp the ratio)."""\n    s = x.float().pow(2); top = s.topk(drop, dim=-1).values.sum(-1)\n    return ((s.sum(-1) - top) / (x.shape[-1] - drop)).sqrt()\n\n\ndef materialize(net32, arch, device=None, half=None):\n    """Physically smaller weights for the decoder: only what `arch` keeps, in its precision."""\n    device = torch.device(device) if device is not None else net32.dev\n    dt = torch.float16 if (arch.half if half is None else half) else torch.float32\n    mv = lambda t: t.to(device=device, dtype=dt).contiguous()\n    hd, rep = net32.hd, net32.rep; layers = []\n    for i, p in enumerate(net32.L):\n        d = {}\n        if arch.attn[i]:\n            groups = [g for g in range(net32.nkv) if arch.kv[i] >> g & 1]\n            qi = torch.cat([torch.arange(h * hd, (h + 1) * hd) for g in groups for h in range(g * rep, (g + 1) * rep)]).to(net32.dev)\n            ki = torch.cat([torch.arange(g * hd, (g + 1) * hd) for g in groups]).to(net32.dev)\n            d[\'attn\'] = dict(n=mv(p[\'n1\']), q=mv(p[\'q\'][qi]), k=mv(p[\'k\'][ki]), v=mv(p[\'v\'][ki]), o=mv(p[\'o\'][:, qi]), nkv=len(groups))\n        if arch.w[i] >= 0:\n            keep = net32.rank[i][:round(net32.dff * WIDTHS[arch.w[i]])].sort().values\n            d[\'mlp\'] = dict(n=mv(p[\'n2\']), g=mv(p[\'g\'][keep]), u=mv(p[\'u\'][keep]), dn=mv(p[\'dn\'][:, keep]))\n        layers.append(d)\n    return dict(E=mv(net32.E), nf=mv(net32.nf), layers=layers, eps=net32.eps, hd=hd, rep=rep, theta=net32.theta,\n                device=device, dtype=dt)\n\n\ndef n_params(M):\n    n = M[\'E\'].numel() + M[\'nf\'].numel()\n    for d in M[\'layers\']:\n        for part in d.values(): n += sum(v.numel() for v in part.values() if torch.is_tensor(v))\n    return n\n', 'fastgen.py': '"""fastgen.py - lean greedy decoder for an edited SmolLM (the weights materialize() returns), and its timing.\n\nOn a GPU the whole token step (embedding -> every kept sublayer -> output -> argmax -> feed back) is captured once as a\nCUDA graph and replayed, so a token is one launch with no Python in the loop. On CPU the same step runs directly.\nHandles any architecture: removed attention or MLP sublayers, narrower MLPs, fewer head groups, fp32 or fp16.\n"""\nimport time, torch, torch.nn.functional as F\n\n\nclass Decoder:\n    def __init__(self, M, max_len=128):\n        self.M = M; self.dev, self.dt = M[\'device\'], M[\'dtype\']; self.L = max_len; self.hd = M[\'hd\']; self.eps = M[\'eps\']\n        inv = 1.0 / (M[\'theta\'] ** (torch.arange(0, self.hd, 2, dtype=torch.float32) / self.hd))\n        fr = torch.outer(torch.arange(max_len, dtype=torch.float32), inv); emb = torch.cat([fr, fr], -1)\n        self.cos, self.sin = emb.cos().to(self.dev, self.dt), emb.sin().to(self.dev, self.dt)\n        self.layers = []\n        for d in M[\'layers\']:\n            e = {}\n            if \'attn\' in d:\n                a = dict(d[\'attn\']); nkv = a[\'nkv\']\n                a[\'kc\'] = torch.zeros(nkv, max_len, self.hd, device=self.dev, dtype=self.dt)\n                a[\'vc\'] = torch.zeros(nkv, max_len, self.hd, device=self.dev, dtype=self.dt); e[\'attn\'] = a\n            if \'mlp\' in d: e[\'mlp\'] = d[\'mlp\']\n            if e: self.layers.append(e)\n        self.tok = torch.zeros(1, dtype=torch.long, device=self.dev); self.pos = torch.zeros(1, dtype=torch.long, device=self.dev)\n        self.ar = torch.arange(max_len, device=self.dev); self.graph = None\n\n    def _norm(self, x, w): return x * torch.rsqrt(x.float().pow(2).mean(-1, keepdim=True) + self.eps).to(x.dtype) * w\n\n    @staticmethod\n    def _rope(x, c, s):\n        h = x.shape[-1] // 2; return x * c + torch.cat([-x[..., h:], x[..., :h]], -1) * s\n\n    @torch.no_grad()\n    def _step(self):\n        """One greedy token: reads self.tok / self.pos, writes the next token into self.tok, advances self.pos."""\n        M, hd = self.M, self.hd\n        x = M[\'E\'].index_select(0, self.tok)\n        c = self.cos.index_select(0, self.pos); s = self.sin.index_select(0, self.pos)\n        mask = torch.where(self.ar <= self.pos, 0.0, float(\'-inf\')).to(self.dt)\n        for e in self.layers:\n            a = e.get(\'attn\')\n            if a is not None:\n                h = self._norm(x, a[\'n\']); nkv = a[\'nkv\']\n                q = self._rope((h @ a[\'q\'].T).view(-1, hd), c, s); k = self._rope((h @ a[\'k\'].T).view(nkv, hd), c, s)\n                v = (h @ a[\'v\'].T).view(nkv, hd)\n                a[\'kc\'].index_copy_(1, self.pos, k.unsqueeze(1)); a[\'vc\'].index_copy_(1, self.pos, v.unsqueeze(1))\n                att = (q.view(nkv, -1, hd) @ a[\'kc\'].transpose(1, 2)) / hd ** 0.5 + mask\n                x = x + (att.softmax(-1) @ a[\'vc\']).reshape(1, -1) @ a[\'o\'].T\n            m = e.get(\'mlp\')\n            if m is not None:\n                h = self._norm(x, m[\'n\']); x = x + (F.silu(h @ m[\'g\'].T) * (h @ m[\'u\'].T)) @ m[\'dn\'].T\n        self.tok.copy_((self._norm(x, M[\'nf\']) @ M[\'E\'].T).argmax(-1)); self.pos.add_(1)\n\n    def reset(self, ids):\n        for e in self.layers:\n            if \'attn\' in e: e[\'attn\'][\'kc\'].zero_(); e[\'attn\'][\'vc\'].zero_()\n        self.pos.zero_()\n        for t in ids[:-1]:\n            self.tok.fill_(t); self._step()\n        self.tok.fill_(ids[-1])\n\n    def capture(self):\n        if self.dev.type != \'cuda\': return self\n        with torch.cuda.device(self.dev):\n            self.reset([0, 0]); st = torch.cuda.Stream(self.dev); st.wait_stream(torch.cuda.current_stream(self.dev))\n            with torch.cuda.stream(st):\n                for _ in range(3): self._step()\n            torch.cuda.current_stream(self.dev).wait_stream(st)\n            self.graph = torch.cuda.CUDAGraph()\n            with torch.cuda.graph(self.graph): self._step()\n        return self\n\n    def decode(self, n):\n        out = []\n        for _ in range(n):\n            if self.graph is not None: self.graph.replay()\n            else: self._step()\n            out.append(self.tok.clone())\n        return torch.cat(out).tolist()\n\n    def generate(self, ids, n):\n        self.reset(list(ids)); return self.decode(n)\n\n\ndef tok_per_s(dec, ids, runs=5, new_tokens=64):\n    """Tokens per second: best of `runs` timed decodes of `new_tokens` tokens after the same prompt."""\n    cuda = dec.dev.type == \'cuda\'; best = 1e9\n    for _ in range(runs + 1):                         # first run is a warm-up\n        dec.reset(ids)\n        if cuda: torch.cuda.synchronize(dec.dev)\n        t0 = time.perf_counter(); dec.decode(new_tokens)\n        if cuda: torch.cuda.synchronize(dec.dev)\n        best = min(best, time.perf_counter() - t0)\n    return new_tokens / best\n', 'quant.py': '"""quant.py - integer storage formats for weight matrices. Weights are only rounded; nothing is retrained.\n\n    i16   16-bit integers, one scale per row                                              16   bits per weight\n    i8     8-bit integers, one scale per row                                               8   bits per weight\n    n4     4-bit integers in blocks of 32 weights; one 16-bit scale code per block,\n           one scale per row (the block rule is llama.cpp\'s Q4_0: the largest weight maps to -8)   4.5 bits per weight\n\nquantize() returns the arrays the GPU kernels read (fused.py) and the exact float values they stand for, which is\nwhat perplexity is measured on.\n"""\nimport torch\n\nBITS = {\'i16\': 16.0, \'i8\': 8.0, \'n4\': 4.5}\nFORMATS = [\'i16\', \'i8\', \'n4\']                      # in order of fewer bits\n\n\ndef quantize(W, fmt):\n    W = W.float()\n    if fmt in (\'i16\', \'i8\'):\n        m = 32767.0 if fmt == \'i16\' else 127.0\n        s = (W.abs().amax(1) / m).clamp_min(1e-12)\n        q = torch.clamp(torch.round(W / s[:, None]), -m, m)\n        return dict(q=q.to(torch.int16 if fmt == \'i16\' else torch.int8).contiguous(), scale=s.contiguous()), q * s[:, None]\n    if fmt == \'n4\':\n        rows, n = W.shape; assert n % 32 == 0\n        B = W.reshape(rows, n // 32, 32)\n        m = torch.gather(B, 2, B.abs().argmax(2, keepdim=True)).squeeze(2)          # the signed largest weight of each block\n        d = m / -8.0; d = torch.where(d == 0, torch.full_like(d, 1e-12), d)\n        q = torch.clamp(torch.round(B / d[:, :, None]), -8, 7)\n        D = d.abs().amax(1); code = torch.clamp(torch.round(d / D[:, None] * 32767.0), -32767, 32767)\n        rs = D / 32767.0\n        nib = (q + 8).to(torch.uint8).reshape(rows, n // 2, 2)\n        packed = (nib[:, :, 0] | (nib[:, :, 1] << 4)).contiguous()                  # low nibble first\n        deq = (q * (code * rs[:, None])[:, :, None]).reshape(rows, n)\n        return dict(q=packed, code=code.to(torch.int16).contiguous(), scale=rs.contiguous()), deq\n    raise ValueError(fmt)\n\n\nMATS = [\'q\', \'k\', \'v\', \'o\', \'g\', \'u\', \'dn\']         # the weight matrices of a layer (norm weights stay in float)\n\n\ndef quantize_model(P, fmt_of, device):\n    """P: smol.extract() weights. fmt_of(name) -> format, name = \'E\' or (layer, matrix).\n    Returns (arrays for the decoder, a copy of P holding the exact dequantized float weights)."""\n    arrs = {}; Pq = dict(P); Pq[\'layers\'] = []\n    a, deq = quantize(P[\'E\'].to(device), fmt_of(\'E\')); arrs[\'E\'] = (fmt_of(\'E\'), a); Pq[\'E\'] = deq\n    for i, l in enumerate(P[\'layers\']):\n        nl = dict(l)\n        for m in MATS:\n            a, deq = quantize(l[m].to(device), fmt_of((i, m))); arrs[(i, m)] = (fmt_of((i, m)), a); nl[m] = deq\n        Pq[\'layers\'].append(nl)\n    return arrs, Pq\n\n\ndef bytes_per_token(P, fmt_of):\n    """Weight bytes read to produce one token (every matrix once; the embedding/output matrix once)."""\n    b = P[\'E\'].numel() * BITS[fmt_of(\'E\')] / 8\n    for i, l in enumerate(P[\'layers\']):\n        for m in MATS: b += l[m].numel() * BITS[fmt_of((i, m))] / 8\n    return b\n', 'fused.py': '"""fused.py - SmolLM\'s token step as custom GPU kernels that read integer weights, replayed as one CUDA graph.\n\nWhy: with PyTorch ops a token costs ~45 tiny GPU launches per layer and the weights are read as 16/32-bit floats.\nHere every weight matrix is read once per token by one kernel, straight from 16-, 8- or 4-bit integers (quant.py),\nso the time per token follows the number of weight bytes. The small steps (norm, rotary position, attention over\nthe cache, activation, argmax) are one kernel each.\n\n    dec = Fused(P, arrs)                 # P: smol.extract() weights, arrs: quant.quantize_model(...)[0]\n    dec.generate(prompt_ids, 64)         # greedy tokens\n    dec.tok_per_s(prompt_ids)            # timing\n"""\nimport time\nimport numpy as np, cupy as cp, torch\n\nSRC = r\'\'\'\n#define LD4I(p) (*reinterpret_cast<const int4*>(p))\n#define LD4F(p) (*reinterpret_cast<const float4*>(p))\n\n// ---------------------------------------------------------------- weight matrix x vector, from integer weights\n// y[r] (+)= scale[r] * sum_j W[r][j] * x[j].  One warp per row; each lane takes every 32nd 16-byte chunk of the row,\n// so a warp reads 512 contiguous bytes at a time.\nextern "C" __global__ void gemv_i16(const short* __restrict__ W, const float* __restrict__ scale, const float* __restrict__ x,\n                                    float* __restrict__ y, const int rows, const int n, const int add)\n{\n    const int lane = threadIdx.x & 31;\n    const int r = blockIdx.x * (blockDim.x >> 5) + (threadIdx.x >> 5);\n    if (r >= rows) return;\n    const short* row = W + (size_t)r * n;\n    float acc = 0.f;\n    for (int c = lane * 8; c < n; c += 256) {\n        const int4 w = LD4I(row + c); const float4 a = LD4F(x + c), b = LD4F(x + c + 4);\n        acc += (float)(short)(w.x) * a.x + (float)(w.x >> 16) * a.y + (float)(short)(w.y) * a.z + (float)(w.y >> 16) * a.w\n             + (float)(short)(w.z) * b.x + (float)(w.z >> 16) * b.y + (float)(short)(w.w) * b.z + (float)(w.w >> 16) * b.w;\n    }\n    for (int o = 16; o > 0; o >>= 1) acc += __shfl_xor_sync(0xffffffffu, acc, o);\n    if (lane == 0) { const float v = acc * scale[r]; y[r] = add ? y[r] + v : v; }\n}\n\n__device__ __forceinline__ float dot4b(const int w, const float4 x) {\n    return (float)(signed char)(w) * x.x + (float)(signed char)(w >> 8) * x.y + (float)(signed char)(w >> 16) * x.z + (float)(w >> 24) * x.w;\n}\nextern "C" __global__ void gemv_i8(const signed char* __restrict__ W, const float* __restrict__ scale, const float* __restrict__ x,\n                                   float* __restrict__ y, const int rows, const int n, const int add)\n{\n    const int lane = threadIdx.x & 31;\n    const int r = blockIdx.x * (blockDim.x >> 5) + (threadIdx.x >> 5);\n    if (r >= rows) return;\n    const signed char* row = W + (size_t)r * n;\n    float acc = 0.f;\n    for (int c = lane * 16; c < n; c += 512) {\n        const int4 w = LD4I(row + c);\n        acc += dot4b(w.x, LD4F(x + c)) + dot4b(w.y, LD4F(x + c + 4)) + dot4b(w.z, LD4F(x + c + 8)) + dot4b(w.w, LD4F(x + c + 12));\n    }\n    for (int o = 16; o > 0; o >>= 1) acc += __shfl_xor_sync(0xffffffffu, acc, o);\n    if (lane == 0) { const float v = acc * scale[r]; y[r] = add ? y[r] + v : v; }\n}\n\n__device__ __forceinline__ float dot8n(const unsigned int w, const float* xp) {\n    const float4 a = LD4F(xp), b = LD4F(xp + 4);\n    return (float)((int)(w & 15u) - 8) * a.x + (float)((int)((w >> 4) & 15u) - 8) * a.y\n         + (float)((int)((w >> 8) & 15u) - 8) * a.z + (float)((int)((w >> 12) & 15u) - 8) * a.w\n         + (float)((int)((w >> 16) & 15u) - 8) * b.x + (float)((int)((w >> 20) & 15u) - 8) * b.y\n         + (float)((int)((w >> 24) & 15u) - 8) * b.z + (float)((int)(w >> 28) - 8) * b.w;\n}\n// 4-bit weights (nibble = q + 8), 32 weights per 16-byte chunk, one signed 16-bit scale code per chunk\nextern "C" __global__ void gemv_n4(const unsigned char* __restrict__ W, const short* __restrict__ bs, const float* __restrict__ scale,\n                                   const float* __restrict__ x, float* __restrict__ y, const int rows, const int n, const int add)\n{\n    const int lane = threadIdx.x & 31;\n    const int r = blockIdx.x * (blockDim.x >> 5) + (threadIdx.x >> 5);\n    if (r >= rows) return;\n    const int nch = n >> 5;\n    const unsigned char* row = W + (size_t)r * (n >> 1);\n    const short* bsr = bs + (size_t)r * nch;\n    float acc = 0.f;\n    for (int ch = lane; ch < nch; ch += 32) {\n        const int4 w = LD4I(row + ch * 16); const float* xp = x + ch * 32;\n        acc += (float)bsr[ch] * (dot8n((unsigned int)w.x, xp) + dot8n((unsigned int)w.y, xp + 8) + dot8n((unsigned int)w.z, xp + 16) + dot8n((unsigned int)w.w, xp + 24));\n    }\n    for (int o = 16; o > 0; o >>= 1) acc += __shfl_xor_sync(0xffffffffu, acc, o);\n    if (lane == 0) { const float v = acc * scale[r]; y[r] = add ? y[r] + v : v; }\n}\n\n// ---------------------------------------------------------------- embedding row of the current token -> x   (one block of n threads)\nextern "C" __global__ void embed_i16(const short* __restrict__ E, const float* __restrict__ scale, const int* __restrict__ tok, float* __restrict__ x, const int n)\n{ const int t = tok[0], j = threadIdx.x; x[j] = (float)E[(size_t)t * n + j] * scale[t]; }\nextern "C" __global__ void embed_i8(const signed char* __restrict__ E, const float* __restrict__ scale, const int* __restrict__ tok, float* __restrict__ x, const int n)\n{ const int t = tok[0], j = threadIdx.x; x[j] = (float)E[(size_t)t * n + j] * scale[t]; }\nextern "C" __global__ void embed_n4(const unsigned char* __restrict__ E, const short* __restrict__ bs, const float* __restrict__ scale,\n                                    const int* __restrict__ tok, float* __restrict__ x, const int n)\n{\n    const int t = tok[0], j = threadIdx.x; const unsigned char b = E[(size_t)t * (n >> 1) + (j >> 1)];\n    const int nib = (j & 1) ? (b >> 4) : (b & 15);\n    x[j] = (float)(nib - 8) * ((float)bs[(size_t)t * (n >> 5) + (j >> 5)] * scale[t]);\n}\n\n// ---------------------------------------------------------------- RMS norm: h = x * rsqrt(mean(x^2) + eps) * w   (one block of n threads)\nextern "C" __global__ void prep(const float* __restrict__ x, const float* __restrict__ w, float* __restrict__ h, const int n, const float eps)\n{\n    __shared__ float red[32];\n    const int t = threadIdx.x; const float v = x[t]; float s = v * v;\n    for (int o = 16; o > 0; o >>= 1) s += __shfl_xor_sync(0xffffffffu, s, o);\n    if ((t & 31) == 0) red[t >> 5] = s;\n    __syncthreads();\n    float tot = 0.f; const int nw = blockDim.x >> 5;\n    for (int i = 0; i < nw; i++) tot += red[i];\n    h[t] = v * rsqrtf(tot / (float)n + eps) * w[t];\n}\n\n// ---------------------------------------------------------------- attention\n// rotate this token\'s keys and store keys and values in the cache.   grid = key/value groups, block = 64\nextern "C" __global__ void kvwrite(const float* __restrict__ k, const float* __restrict__ v, const float* __restrict__ cs, const float* __restrict__ sn,\n                                   float* __restrict__ KC, float* __restrict__ VC, const int* __restrict__ posp, const int L)\n{\n    const int g = blockIdx.x, i = threadIdx.x, pos = posp[0];\n    const float kv = k[g * 64 + i]; const float other = (i < 32) ? -k[g * 64 + i + 32] : k[g * 64 + i - 32];\n    const size_t o = ((size_t)g * L + pos) * 64 + i;\n    KC[o] = kv * cs[pos * 64 + i] + other * sn[pos * 64 + i];\n    VC[o] = v[g * 64 + i];\n}\n// one block per query head, one thread per cache position (block = L threads, L a multiple of 32, <= 1024)\nextern "C" __global__ void attn(const float* __restrict__ q, const float* __restrict__ cs, const float* __restrict__ sn,\n                                const float* __restrict__ KC, const float* __restrict__ VC, float* __restrict__ out,\n                                const int* __restrict__ posp, const int L, const int rep)\n{\n    __shared__ float qr[64]; __shared__ float wgt[1024]; __shared__ float red[32];\n    const int hh = blockIdx.x, g = hh / rep, t = threadIdx.x, pos = posp[0], nw = blockDim.x >> 5;\n    if (t < 64) {\n        const float qv = q[hh * 64 + t]; const float other = (t < 32) ? -q[hh * 64 + t + 32] : q[hh * 64 + t - 32];\n        qr[t] = qv * cs[pos * 64 + t] + other * sn[pos * 64 + t];\n    }\n    __syncthreads();\n    float sc = -1e30f;\n    if (t <= pos) {\n        const float* kp = KC + ((size_t)g * L + t) * 64; float d = 0.f;\n        for (int i = 0; i < 64; i++) d += qr[i] * kp[i];\n        sc = d * 0.125f;\n    }\n    float m = sc;\n    for (int o = 16; o > 0; o >>= 1) m = fmaxf(m, __shfl_xor_sync(0xffffffffu, m, o));\n    if ((t & 31) == 0) red[t >> 5] = m;\n    __syncthreads();\n    float mx = -1e30f;\n    for (int i = 0; i < nw; i++) mx = fmaxf(mx, red[i]);\n    __syncthreads();\n    const float e = (t <= pos) ? expf(sc - mx) : 0.f;\n    float s = e;\n    for (int o = 16; o > 0; o >>= 1) s += __shfl_xor_sync(0xffffffffu, s, o);\n    if ((t & 31) == 0) red[t >> 5] = s;\n    wgt[t] = e;\n    __syncthreads();\n    float tot = 0.f;\n    for (int i = 0; i < nw; i++) tot += red[i];\n    if (t < 64) {\n        const float* vp = VC + (size_t)g * L * 64 + t; float o = 0.f;\n        for (int p = 0; p <= pos; p++) o += wgt[p] * vp[(size_t)p * 64];\n        out[hh * 64 + t] = o / tot;\n    }\n}\n\n// ---------------------------------------------------------------- MLP activation: a = silu(g) * u\nextern "C" __global__ void act(const float* __restrict__ g, const float* __restrict__ u, float* __restrict__ a, const int n)\n{ const int i = blockIdx.x * blockDim.x + threadIdx.x; if (i < n) { const float v = g[i]; a[i] = v / (1.f + expf(-v)) * u[i]; } }\n\n// ---------------------------------------------------------------- greedy pick: per-block winners, then the overall winner\nextern "C" __global__ void argmax1(const float* __restrict__ lg, float* __restrict__ bm, int* __restrict__ bi, const int n)\n{\n    __shared__ float sm[32]; __shared__ int si[32];\n    const int t = threadIdx.x, i = blockIdx.x * blockDim.x + t;\n    float v = (i < n) ? lg[i] : -3.4e38f; int idx = i;\n    for (int o = 16; o > 0; o >>= 1) {\n        const float v2 = __shfl_xor_sync(0xffffffffu, v, o); const int i2 = __shfl_xor_sync(0xffffffffu, idx, o);\n        if (v2 > v || (v2 == v && i2 < idx)) { v = v2; idx = i2; }\n    }\n    if ((t & 31) == 0) { sm[t >> 5] = v; si[t >> 5] = idx; }\n    __syncthreads();\n    if (t == 0) {\n        float bv = sm[0]; int bx = si[0];\n        for (int w = 1; w < (blockDim.x >> 5); w++) if (sm[w] > bv || (sm[w] == bv && si[w] < bx)) { bv = sm[w]; bx = si[w]; }\n        bm[blockIdx.x] = bv; bi[blockIdx.x] = bx;\n    }\n}\n// writes the next token, records it, advances the position   (one block of nb threads, nb a multiple of 32)\nextern "C" __global__ void argmax2(const float* __restrict__ bm, const int* __restrict__ bi, int* __restrict__ tok, int* __restrict__ pos,\n                                   int* __restrict__ outbuf, const int nb)\n{\n    __shared__ float sm[32]; __shared__ int si[32];\n    const int t = threadIdx.x;\n    float v = (t < nb) ? bm[t] : -3.4e38f; int idx = (t < nb) ? bi[t] : 0x7fffffff;\n    for (int o = 16; o > 0; o >>= 1) {\n        const float v2 = __shfl_xor_sync(0xffffffffu, v, o); const int i2 = __shfl_xor_sync(0xffffffffu, idx, o);\n        if (v2 > v || (v2 == v && i2 < idx)) { v = v2; idx = i2; }\n    }\n    if ((t & 31) == 0) { sm[t >> 5] = v; si[t >> 5] = idx; }\n    __syncthreads();\n    if (t == 0) {\n        float bv = sm[0]; int bx = si[0];\n        for (int w = 1; w < (blockDim.x >> 5); w++) if (sm[w] > bv || (sm[w] == bv && si[w] < bx)) { bv = sm[w]; bx = si[w]; }\n        const int p = pos[0]; tok[0] = bx; outbuf[p] = bx; pos[0] = p + 1;\n    }\n}\n\'\'\'\n_K = {}\ndef K(name):\n    if name not in _K: _K[name] = cp.RawKernel(SRC, name)\n    return _K[name]\n\ni32 = np.int32\n\n\ndef _cp(t):\n    """A CuPy-owned copy of a torch tensor."""\n    return cp.asarray(t.contiguous()).copy() if t.is_cuda else cp.asarray(t.detach().contiguous().numpy())\n\n\nclass Fused:\n    def __init__(self, P, arrs, max_len=128, rpb=4, device=0):\n        self.dev = cp.cuda.Device(device); self.L = max_len; assert max_len % 32 == 0 and max_len <= 1024\n        self.rpb = rpb if callable(rpb) else (lambda rows, n, fmt: rpb)\n        with self.dev:\n            d = P[\'E\'].shape[1]; V = P[\'E\'].shape[0]; hd, nq, nkv = P[\'hd\'], P[\'nq\'], P[\'nkv\']; dff = P[\'layers\'][0][\'g\'].shape[0]\n            assert hd == 64 and d % 32 == 0 and d <= 1024\n            self.d, self.V = d, V; f32 = cp.float32\n            z = lambda n, dt=f32: cp.zeros(n, dt)\n            self.x, self.h, self.q, self.k, self.v, self.oin = z(d), z(d), z(nq * hd), z(nkv * hd), z(nkv * hd), z(nq * hd)\n            self.g, self.u, self.a, self.lg = z(dff), z(dff), z(dff), z(V)\n            nb = -(-V // 256); self.nb = -(-nb // 32) * 32; self.bm, self.bi = z(self.nb), z(self.nb, cp.int32)\n            self.tok, self.pos, self.out = z(1, cp.int32), z(1, cp.int32), z(max_len, cp.int32)\n            inv = 1.0 / (P[\'theta\'] ** (np.arange(0, hd, 2, dtype=np.float32) / hd))\n            fr = np.outer(np.arange(max_len, dtype=np.float32), inv); emb = np.concatenate([fr, fr], -1)\n            cs, sn = cp.asarray(np.cos(emb).astype(np.float32)), cp.asarray(np.sin(emb).astype(np.float32))\n            self.keep = [cs, sn]; eps = np.float32(P[\'eps\']); self.launches = []\n            A = {name: (fmt, {k: _cp(v) for k, v in a.items()}) for name, (fmt, a) in arrs.items()}; self.A = A\n\n            def gemv(name, rows, n, x, y, add):\n                fmt, a = A[name]; r = self.rpb(rows, n, fmt)\n                args = (a[\'q\'], a[\'code\'], a[\'scale\'], x, y, i32(rows), i32(n), i32(add)) if fmt == \'n4\' else (a[\'q\'], a[\'scale\'], x, y, i32(rows), i32(n), i32(add))\n                self.launches.append((K(\'gemv_\' + fmt), ((rows + r - 1) // r,), (32 * r,), args))\n\n            def norm(w):\n                wv = _cp(w.float()); self.keep.append(wv)\n                self.launches.append((K(\'prep\'), (1,), (d,), (self.x, wv, self.h, i32(d), eps)))\n\n            fmt, a = A[\'E\']\n            self.launches.append((K(\'embed_\' + fmt), (1,), (d,), ((a[\'q\'], a[\'code\'], a[\'scale\'], self.tok, self.x, i32(d)) if fmt == \'n4\'\n                                                                  else (a[\'q\'], a[\'scale\'], self.tok, self.x, i32(d)))))\n            for i, l in enumerate(P[\'layers\']):\n                KC, VC = z(nkv * max_len * hd), z(nkv * max_len * hd); self.keep += [KC, VC]\n                norm(l[\'n1\'])\n                gemv((i, \'q\'), nq * hd, d, self.h, self.q, 0); gemv((i, \'k\'), nkv * hd, d, self.h, self.k, 0); gemv((i, \'v\'), nkv * hd, d, self.h, self.v, 0)\n                self.launches.append((K(\'kvwrite\'), (nkv,), (64,), (self.k, self.v, cs, sn, KC, VC, self.pos, i32(max_len))))\n                self.launches.append((K(\'attn\'), (nq,), (max_len,), (self.q, cs, sn, KC, VC, self.oin, self.pos, i32(max_len), i32(nq // nkv))))\n                gemv((i, \'o\'), d, nq * hd, self.oin, self.x, 1)\n                norm(l[\'n2\'])\n                gemv((i, \'g\'), dff, d, self.h, self.g, 0); gemv((i, \'u\'), dff, d, self.h, self.u, 0)\n                self.launches.append((K(\'act\'), (-(-dff // 256),), (256,), (self.g, self.u, self.a, i32(dff))))\n                gemv((i, \'dn\'), d, dff, self.a, self.x, 1)\n            norm(P[\'nf\'])\n            gemv(\'E\', V, d, self.h, self.lg, 0)\n            self.launches.append((K(\'argmax1\'), (nb,), (256,), (self.lg, self.bm, self.bi, i32(V))))\n            self.launches.append((K(\'argmax2\'), (1,), (self.nb,), (self.bm, self.bi, self.tok, self.pos, self.out, i32(nb))))\n\n            self.stream = cp.cuda.Stream(non_blocking=True)\n            with self.stream:\n                self._step(); self.stream.synchronize()                 # compiles every kernel\n                self.stream.begin_capture(); self._step(); self.graph = self.stream.end_capture()\n                self.pos[...] = 0; self.stream.synchronize()\n\n    def _step(self):\n        for k, grid, block, args in self.launches: k(grid, block, args)\n\n    def breakdown(self, reps=10):\n        """Milliseconds per token spent in each kind of kernel (each kind replayed alone as its own graph)."""\n        out = {}\n        with self.dev:\n            names = {id(v): n for n, v in _K.items()}\n            for kind in sorted({names[id(l[0])] for l in self.launches}):\n                sub = [l for l in self.launches if names[id(l[0])] == kind]; s = cp.cuda.Stream(non_blocking=True)\n                with s:\n                    self.pos[...] = 0; s.synchronize(); s.begin_capture()\n                    for k, grid, block, args in sub: k(grid, block, args)\n                    g = s.end_capture(); best = 1e9\n                    for _ in range(reps):\n                        self.pos[...] = 0; s.synchronize(); t0 = time.perf_counter(); g.launch(s); s.synchronize(); best = min(best, time.perf_counter() - t0)\n                out[kind] = dict(launches=len(sub), ms=round(best * 1000, 4))\n            with self.stream: self.pos[...] = 0; self.stream.synchronize()\n        return out\n\n    def _feed(self, ids):\n        self.pos[...] = 0\n        for t in ids[:-1]:\n            self.tok[...] = int(t); self.graph.launch(self.stream)\n        self.tok[...] = int(ids[-1])\n\n    def generate(self, ids, n):\n        assert len(ids) + n <= self.L\n        with self.dev, self.stream:\n            self._feed(ids)\n            for _ in range(n): self.graph.launch(self.stream)\n            self.stream.synchronize()\n            return cp.asnumpy(self.out[len(ids) - 1:len(ids) - 1 + n]).tolist()\n\n    def first_logits(self, ids):\n        """Logits after the last prompt token (for checking against a reference)."""\n        with self.dev, self.stream:\n            self._feed(ids); self.graph.launch(self.stream); self.stream.synchronize()\n            return torch.as_tensor(cp.asnumpy(self.lg))\n\n    def tok_per_s(self, ids, runs=5, new_tokens=64):\n        best = 1e9\n        with self.dev, self.stream:\n            for _ in range(runs + 1):\n                self._feed(ids); self.stream.synchronize(); t0 = time.perf_counter()\n                for _ in range(new_tokens): self.graph.launch(self.stream)\n                self.stream.synchronize(); best = min(best, time.perf_counter() - t0)\n        return new_tokens / best\n', 'agent.py': '"""agent.py - a ~1K-parameter neural network learns, by reinforcement, how to edit SmolLM-135M so it generates faster.\n\nEPISODES. Every episode starts from the original model. Each step the network looks at every edit that is still\npossible anywhere in the architecture and picks one:\n    attn i      remove the attention sublayer of layer i\n    mlp i       remove the MLP sublayer of layer i\n    p10 / p30   remove another 10% / 30% of layer i\'s MLP neurons (the least-used ones)\n    kv i g      remove key/value head group g of layer i (with its 3 query heads)\n    half        run the weights in 16-bit floats (GPU only)\nWeights are only kept, removed or stored in fewer bits. Nothing is retrained.\nAn edit that would push search perplexity past the budget is refused (a strike, small penalty); three strikes end the\nepisode. So every episode ends on a model that is inside the budget, and its return is that model\'s speed-up.\n\nREWARD (fixed; the network cannot change it): 10 x the speed gained by each accepted edit, -0.2 per refused edit.\nSpeed during an episode comes from a latency model fitted to real decoder timings on this machine at start-up.\nPerplexity is exact (smol.py) and judged pessimistically: mean increase + one standard error must stay within 10%.\nThe search text is split into subsets and every episode is scored on the next one, so the network cannot profit\nfrom the noise of one particular piece of text.\n\nLEARNING. PPO-style policy gradient on the network\'s own episodes, with a small linear baseline.\n\nSAFEGUARDS (scoring side, outside the agent): an architecture becomes the saved best only if it is within budget on\nthe WHOLE search text, VALIDATION perplexity is also within 10%, AND its speed, timed for real with the decoder, beats\nthe best so far. Test text is used once, for the final report.\n"""\nimport os, json, math, time, copy, threading, statistics\nimport torch, torch.nn as nn\nimport judge as J, smol as S, fastgen as G\n\nLOOP = float(os.environ.get(\'LOOP_SECONDS\', 300))\nOUT = os.environ.get(\'OUT_DIR\', f\'{J.ROOT}/runs_v3\'); os.makedirs(OUT, exist_ok=True)\nSEED = int(os.environ.get(\'SEED\', 0))\nTOL = 1.10; BUDGET = math.log(TOL)\nTMAX, STRIKES = 60, 3\nROUND_EPISODES = int(os.environ.get(\'ROUND_EPISODES\', 4)); SUBSETS = int(os.environ.get(\'SUBSETS\', 4))\nCAL_RUNS = int(os.environ.get(\'CAL_RUNS\', 5)); CAL_TOKENS = int(os.environ.get(\'CAL_TOKENS\', 64))   # decoder timing: best of N runs of T tokens\nLR, EPOCHS, CLIP, ENT = 0.01, 4, 0.2, 0.01\nTIMING_TOL = float(os.environ.get(\'TIMING_TOL\', 0.01))      # real speed must confirm the latency model within this\nFEAT = 18\nT0 = time.time()\n\n\ndef say(**k):\n    k[\'t\'] = round(time.time() - T0, 1); print(json.dumps(k), flush=True)\n\n\n# ----------------------------------------------------------------------------------------------- the 1K network\nclass Policy(nn.Module):\n    def __init__(self):\n        super().__init__()\n        self.net = nn.Sequential(nn.Linear(FEAT, 32), nn.Tanh(), nn.Linear(32, 12), nn.Tanh(), nn.Linear(12, 1))\n        with torch.no_grad(): self.net[-1].weight.mul_(0.1); self.net[-1].bias.zero_()\n\n    def forward(self, f): return self.net(f).squeeze(-1)\n\n\n# ----------------------------------------------------------------------------------------------- latency model\nclass Latency:\n    """ms per token = fixed + per kept attention sublayer (A0 + A1 x share of head groups kept)\n                            + per kept MLP sublayer (M0 + M1 x width).   Five numbers per precision."""\n\n    def __init__(self, nkv): self.coef = {}; self.nkv = nkv; self.ms0 = None\n\n    def ms(self, a):\n        c, A0, A1, M0, M1 = self.coef[a.half]; t = c\n        for i in range(len(a.attn)):\n            if a.attn[i]: t += A0 + A1 * bin(a.kv[i]).count(\'1\') / self.nkv\n            if a.w[i] >= 0: t += M0 + M1 * S.WIDTHS[a.w[i]]\n        return t\n\n    def speedup(self, a): return self.ms0 / self.ms(a)\n\n\ndef calibrate(w, halves):\n    """Fit the latency model from real decoder timings. Every architecture that fits the perplexity budget is close\n    to the full model, so the model is fitted there: time the full model, then the full model with one kind of part\n    taken out of a third of the layers (or thinned in all of them). A mixed architecture that was not used for the\n    fit checks the prediction."""\n    net = w.n32; nl, nkv = net.NL, net.nkv; lat = Latency(nkv); info = {}; k3 = [i for i in range(nl) if i % 3 == 1]\n    for half in halves:\n        def mk(fn):\n            a = net.full(); a.half = half\n            for i in range(nl): fn(a, i)\n            return a\n        def mixed(a, i):\n            if i % 6 == 0: a.attn[i] = False\n            elif i % 6 == 3: a.kv[i] = 0b011\n            if i % 10 == 5: a.w[i] = -1\n            elif i % 5 == 1: a.w[i] = 3\n            elif i % 5 == 2: a.w[i] = 5\n        archs = dict(full=mk(lambda a, i: None), attn_third=mk(lambda a, i: a.attn.__setitem__(i, i % 3 != 1)),\n                     mlp_third=mk(lambda a, i: a.w.__setitem__(i, -1 if i % 3 == 1 else 0)),\n                     mlp50=mk(lambda a, i: a.w.__setitem__(i, 5)), kv1=mk(lambda a, i: a.kv.__setitem__(i, 1)), mixed=mk(mixed))\n        t = {k: 1000.0 / w.tok_s(a, CAL_RUNS, CAL_TOKENS) for k, a in archs.items()}\n        A = (t[\'full\'] - t[\'attn_third\']) / len(k3); M = (t[\'full\'] - t[\'mlp_third\']) / len(k3)\n        M1 = (t[\'full\'] - t[\'mlp50\']) / (0.5 * nl); A1 = (t[\'full\'] - t[\'kv1\']) / (nl * (1 - 1 / nkv))\n        lat.coef[half] = (t[\'full\'] - nl * (A + M), A - A1, A1, M - M1, M1)\n        pred = lat.ms(archs[\'mixed\'])\n        info[\'fp16\' if half else \'fp32\'] = dict(ms={k: round(v, 3) for k, v in t.items()},\n            attn_sublayer_ms=round(A, 4), kv_group_ms=round(A1 / nkv, 4), mlp_sublayer_ms=round(M, 4), mlp_width_part_ms=round(M1, 4),\n            check_pred_ms=round(pred, 3), check_real_ms=round(t[\'mixed\'], 3), check_error_pct=round(100 * (pred / t[\'mixed\'] - 1), 2))\n    lat.ms0 = lat.ms(net.full())\n    return lat, info\n\n\n# ----------------------------------------------------------------------------------------------- shared knowledge\nclass Shared:\n    """What every worker reads: the latency model, usage statistics and single-edit probe costs of the original\n    model, and a memo of architectures already scored."""\n    def __init__(self): self.memo = {}; self.evals = 0; self.hits = 0; self.allow_half = False\n\n\ndef candidates(arch, blocked, allow_half, nkv):\n    c = []\n    for i in range(len(arch.attn)):\n        if arch.attn[i]:\n            c.append((\'attn\', i))\n            if bin(arch.kv[i]).count(\'1\') > 1:\n                c.extend((\'kv\', i, g) for g in range(nkv) if arch.kv[i] >> g & 1)\n        if arch.w[i] >= 0:\n            c.append((\'mlp\', i))\n            if arch.w[i] + 1 < len(S.WIDTHS): c.append((\'p10\', i))\n            if arch.w[i] + 3 < len(S.WIDTHS): c.append((\'p30\', i))\n    if allow_half and not arch.half: c.append((\'half\',))\n    return [e for e in c if e not in blocked] if blocked else c\n\n\ndef features(arch, cands, used, s_cur, strikes, sh):\n    """One row of FEAT numbers per possible edit: what it is, where it is, the state of that layer, what the latency\n    model says it saves, what it cost when probed alone on the original model, how much that part writes into the\n    residual stream, and the episode\'s state (budget used, speed so far, strikes)."""\n    lat = sh.lat; nkv = lat.nkv; nl = len(arch.attn); ms0 = lat.ms0; ms_cur = lat.ms(arch)\n    c, A0, A1, M0, M1 = lat.coef[arch.half]\n    g_state = [min(1.5, max(0.0, used / BUDGET)), s_cur - 1, strikes / STRIKES, 1.0 if arch.half else 0.0]\n    rows, gains = [], []\n    for e in cands:\n        k = e[0]; f = [0.0] * FEAT\n        if k == \'half\':\n            f[4] = 1.0; ms_new = lat.ms(arch.apply(e)); cost = 0.0; wr = 0.0; rem = 0.0\n        else:\n            i = e[1]; nk = bin(arch.kv[i]).count(\'1\'); wi = arch.w[i]; wcur = S.WIDTHS[wi] if wi >= 0 else 0.0\n            if k == \'attn\':\n                f[0] = 1.0; d = A0 + A1 * nk / nkv; cost = sh.p_attn[i]; wr = sh.aw[i] * nk / nkv; rem = nk / nkv\n            elif k == \'mlp\':\n                f[1] = 1.0; d = M0 + M1 * wcur; cost = sh.p_mlp[i] - sh.p_w[i][wi]; wr = sh.mw[i] * (1 - sh.mass[i][wi]); rem = wcur\n            elif k == \'kv\':\n                f[3] = 1.0; d = A1 / nkv; cost = sh.p_kv[i][e[2]]; wr = sh.kw[i][e[2]]; rem = 1 / nkv\n            else:\n                f[2] = 1.0; nw = wi + (1 if k == \'p10\' else 3); d = M1 * (wcur - S.WIDTHS[nw])\n                cost = sh.p_w[i][nw] - sh.p_w[i][wi]; wr = sh.mw[i] * (sh.mass[i][nw] - sh.mass[i][wi]); rem = wcur - S.WIDTHS[nw]\n            ms_new = ms_cur - d\n            f[5] = i / (nl - 1); f[10] = wcur; f[11] = nk / nkv if arch.attn[i] else 0.0\n            nb = [(not arch.attn[j]) if k in (\'attn\', \'kv\') else arch.w[j] < 0 for j in (i - 1, i + 1) if 0 <= j < nl]\n            f[15] = sum(nb) / 2\n        gain = ms0 / ms_new - ms0 / ms_cur\n        cf = cost / BUDGET\n        f[6] = 10 * gain; f[7] = max(-0.5, min(3.0, cf)); f[8] = min(2.0, wr); f[9] = rem\n        f[12:16] = g_state[:3] + [f[15]]; f[16] = g_state[3]\n        f[17] = max(-2.5, math.log10(max(gain, 1e-5) / max(cf, 0.01)) / 2)        # speed gained per share of budget\n        rows.append(f); gains.append(gain)\n    return torch.tensor(rows, dtype=torch.float32), gains\n\n\n# ----------------------------------------------------------------------------------------------- one worker = one device\nclass Worker:\n    def __init__(self, dev, P, sh):\n        self.dev = torch.device(dev); self.cuda = self.dev.type == \'cuda\'; self.sh = sh\n        self.n32 = S.Net(P, dev, half=False, T=J.SEQ)\n        self.n16 = S.Net(P, dev, half=True, T=J.SEQ) if self.cuda else None\n        self.nS = self.n32                                     # the net search-time evaluations run on\n        pool = J.split(\'search\').to(self.dev); self.T = pool.shape[1]; self.n = len(pool) // SUBSETS\n        self.ids = [pool[k * self.n:(k + 1) * self.n] for k in range(SUBSETS)]      # the rotating search subsets\n        self.prompt = J.tokenizer()(J.PROMPTS[0])[\'input_ids\']\n        self.data = {}; self.base = {}; self.eval_s = 0.0; self.busy_s = 0.0\n\n    @torch.no_grad()\n    def tok_s(self, arch, runs, toks):\n        dec = G.Decoder(S.materialize(self.n32, arch)).capture(); r = G.tok_per_s(dec, self.prompt, runs, toks)\n        del dec\n        return r\n\n    @torch.no_grad()\n    def load_split(self, name):\n        self.data[name] = J.split(name).to(self.dev)\n        self.base[name] = self.n32.seq_nll(self.data[name], self.n32.full())\n\n    @torch.no_grad()\n    def ratio(self, name, arch):\n        """Perplexity of `arch` relative to the original on a split, in the architecture\'s own precision."""\n        net = self.n16 if (arch.half and self.cuda) else self.n32\n        d = (net.seq_nll(self.data[name], arch) - self.base[name]) / (self.T - 1)\n        md = d.mean().item(); se = d.std().item() / math.sqrt(len(d))\n        return dict(ratio=math.exp(md) if math.isfinite(md) else float(\'inf\'), se_pct=round(100 * se, 3))\n\n    @torch.no_grad()\n    def make_root(self):\n        """Residual stream of the original model entering every layer, per search subset (the prefix cache)."""\n        net = self.nS; full = net.full(); self.root, self.root_b = [], []\n        self.bases = [self.base[\'search\'][k * self.n:(k + 1) * self.n] for k in range(SUBSETS)]\n        for k in range(SUBSETS):\n            acts = [net.embed(self.ids[k])]\n            for i in range(net.NL): acts.append(net.layer(i, acts[-1], full))\n            self.root.append(acts); self.root_b.append(self._bound(net.nll(acts[-1], self.ids[k]), k))\n\n    def _bound(self, nll, k):\n        d = (nll - self.bases[k]) / (self.T - 1)\n        return d.mean().item(), d.std().item() / math.sqrt(len(d))\n\n    @torch.no_grad()\n    def eval_edit(self, new, i, acts, valid, k):\n        """Score `new` on subset k. It differs from the architecture behind `acts` only at layer i, so recompute from\n        the first layer that can have changed; everything before it comes from the cache."""\n        t0 = time.perf_counter(); net = self.nS; s = min(i, valid); x = acts[s]; tmp = {}\n        for j in range(s, net.NL):\n            x = net.layer(j, x, new); tmp[j + 1] = x\n        md, se = self._bound(net.nll(x, self.ids[k]), k); self.eval_s += time.perf_counter() - t0\n        return md, se, tmp, s\n\n    @torch.no_grad()\n    def pool_bound(self, arch):\n        """Mean and standard error of the NLL increase over the whole search text (all subsets)."""\n        d = torch.cat([(self.nS.seq_nll(self.ids[k], arch) - self.bases[k]) / (self.T - 1) for k in range(SUBSETS)])\n        return d.mean().item(), d.std().item() / math.sqrt(len(d))\n\n    @torch.no_grad()\n    def probe(self, edits):\n        """Cost (mean increase of search NLL per token, subset 0) of single edits applied alone to the original model."""\n        out = {}\n        for name, arch, i in edits:\n            md, se, _, _ = self.eval_edit(arch, i, self.root[0], self.nS.NL, 0); out[name] = md - self.root_b[0][0]\n            self.sh.memo[(0, arch.key())] = (md, se)\n        return out\n\n    @torch.no_grad()\n    def bench(self):\n        """Seconds for one from-scratch scoring of an architecture on one subset: the layers, and the loss."""\n        net = self.nS; full = net.full(); best = [1e9, 1e9]\n        sync = (lambda: torch.cuda.synchronize(self.dev)) if self.cuda else (lambda: None)\n        for _ in range(3):\n            sync(); t0 = time.perf_counter(); x = net.embed(self.ids[0])\n            for i in range(net.NL): x = net.layer(i, x, full)\n            sync(); t1 = time.perf_counter(); net.nll(x, self.ids[0]); sync(); t2 = time.perf_counter()\n            best = [min(best[0], t1 - t0), min(best[1], t2 - t1)]\n        return dict(layers_s=round(best[0], 4), loss_s=round(best[1], 4))\n\n    @torch.no_grad()\n    def episode(self, pol, gen, k=0, greedy=False, chooser=None):\n        t_ep = time.perf_counter()\n        sh = self.sh; NL = self.nS.NL; arch = self.nS.full(); acts = list(self.root[k]); valid = NL\n        md, se = self.root_b[k]; sc = 1.0; strikes = 0; blocked = set(); tr = []; acc = []; rej = []\n        while strikes < STRIKES and len(tr) < TMAX:\n            cands = candidates(arch, blocked, sh.allow_half, sh.lat.nkv)\n            if not cands: break\n            F, gains = features(arch, cands, md + se, sc, strikes, sh)\n            if chooser is not None: a = chooser(F); lp = 0.0\n            else:\n                ls = torch.log_softmax(pol(F), 0)\n                a = int(ls.argmax()) if greedy else int(torch.multinomial(ls.exp(), 1, generator=gen))\n                lp = float(ls[a])\n            e = cands[a]; new = arch.apply(e); rem = 1 - (md + se) / BUDGET\n            phi = [1.0, rem, rem * rem, strikes / STRIKES, 1.0 if arch.half else 0.0, sc - 1]\n            computed = False\n            if e[0] == \'half\': nmd, nse = md, se               # search evaluations already run in this precision\n            else:\n                hit = sh.memo.get((k, new.key()))\n                if hit is not None: nmd, nse = hit; sh.hits += 1\n                else:\n                    nmd, nse, tmp, s = self.eval_edit(new, e[1], acts, valid, k); sh.memo[(k, new.key())] = (nmd, nse)\n                    computed = True; sh.evals += 1\n                    for j in range(s + 1, e[1] + 1): acts[j] = tmp[j]\n                    valid = max(valid, e[1])\n            if math.isfinite(nmd) and nmd + nse <= BUDGET:\n                r = 10 * gains[a]; arch = new; sc += gains[a]; md, se = nmd, nse; acc.append(e)\n                if e[0] != \'half\':\n                    if computed:\n                        for j in range(e[1] + 1, NL + 1): acts[j] = tmp[j]\n                        valid = NL\n                    else: valid = min(valid, e[1])\n            else:\n                r = -0.2; strikes += 1; blocked.add(e); rej.append(e)\n            tr.append(dict(F=F, a=a, lp=lp, r=r, phi=phi))\n        self.busy_s += time.perf_counter() - t_ep\n        return dict(tr=tr, arch=arch, S=sc, md=md, se=se, acc=acc, rej=rej, k=k)\n\n\ndef run_round(workers, pol, gens, n, counter):\n    """n episodes shared between the workers (each takes the next one as soon as it is free). Every episode is\n    scored on the next search subset in turn."""\n    out = []; lock = threading.Lock(); left = [n]\n    def loop(w, gen):\n        while True:\n            with lock:\n                if left[0] <= 0: return\n                left[0] -= 1; k = counter[0] % SUBSETS; counter[0] += 1\n            ep = w.episode(pol, gen, k)\n            with lock: out.append(ep)\n    th = [threading.Thread(target=loop, args=(w, g)) for w, g in zip(workers, gens)]\n    for t in th: t.start()\n    for t in th: t.join()\n    return out\n\n\ndef update(pol, opt, trans):\n    """PPO-clip on this round\'s steps (all steps in one padded batch)."""\n    N = len(trans); C = max(t[\'F\'].shape[0] for t in trans)\n    Fp = torch.zeros(N, C, FEAT); mask = torch.zeros(N, C, dtype=torch.bool)\n    for n, t in enumerate(trans):\n        c = t[\'F\'].shape[0]; Fp[n, :c] = t[\'F\']; mask[n, :c] = True\n    act = torch.tensor([t[\'a\'] for t in trans])[:, None]; lp0 = torch.tensor([t[\'lp\'] for t in trans]); adv = torch.stack([t[\'adv\'] for t in trans])\n    for _ in range(EPOCHS):\n        ls = torch.log_softmax(pol(Fp).masked_fill(~mask, -1e9), 1)\n        ratio = torch.exp(ls.gather(1, act).squeeze(1) - lp0)\n        ent = -(ls.exp() * ls).masked_fill(~mask, 0.0).sum(1)\n        loss = (-torch.min(ratio * adv, ratio.clamp(1 - CLIP, 1 + CLIP) * adv) - ENT * ent).mean()\n        opt.zero_grad(); loss.backward(); nn.utils.clip_grad_norm_(pol.parameters(), 1.0); opt.step()\n\n\ndef main():\n    torch.manual_seed(SEED)\n    devs = [f\'cuda:{i}\' for i in range(torch.cuda.device_count())] or [\'cpu\']\n    say(event=\'setup\', devices=[torch.cuda.get_device_name(i) for i in range(len(devs))] if devs[0] != \'cpu\' else [\'cpu\'],\n        loop_seconds=LOOP, search_seqs=J.SIZES[\'search\'], search_subsets=SUBSETS, validation_seqs=J.SIZES[\'validation\'],\n        test_seqs=J.SIZES[\'test\'], seq_len=J.SEQ)\n    from transformers import AutoModelForCausalLM\n    P = S.extract(AutoModelForCausalLM.from_pretrained(J.MODEL_DIR, dtype=torch.float32))\n    sh = Shared(); workers = [Worker(d, P, sh) for d in devs]; w0 = workers[0]; NL, nkv = w0.n32.NL, w0.n32.nkv\n    sh.NL, sh.nkv = NL, nkv\n\n    # ---- usage statistics of the original model (calibration text) -> which neurons count as most-used\n    st = w0.n32.stats(J.split(\'calib\').to(w0.dev)); rank = [v.argsort(descending=True) for v in st[\'imp\']]\n    sh.aw, sh.mw, sh.kw = st[\'aw\'].tolist(), st[\'mw\'].tolist(), st[\'kw\'].tolist()\n    sh.mass = [[float(v[r[round(len(v) * wd):]].sum() / v.sum()) for wd in S.WIDTHS] for v, r in zip(st[\'imp\'], rank)]\n    for w in workers:\n        w.n32.set_rank(rank)\n        if w.n16 is not None: w.n16.set_rank(rank)\n        w.load_split(\'search\')\n    for name in (\'validation\', \'test\'): w0.load_split(name)\n    base_ppl = {k: math.exp(v.sum().item() / (v.numel() * (w0.T - 1))) for k, v in w0.base.items()}\n    say(event=\'baseline\', ppl={k: round(v, 3) for k, v in base_ppl.items()})\n\n    # ---- is 16-bit evaluation numerically safe on this model? then search-time scoring runs in 16-bit (faster)\n    if w0.cuda:\n        d0 = ((w0.n16.seq_nll(w0.data[\'search\'], w0.n16.full()) - w0.base[\'search\']) / (w0.T - 1)).mean().item()\n        ok = math.isfinite(d0) and abs(d0) < 0.003; sh.allow_half = ok\n        say(event=\'fp16_check\', nll_shift_per_token=d0, usable=ok)\n        if ok:\n            for w in workers: w.nS = w.n16\n    for w in workers: w.make_root()\n    say(event=\'bench\', one_scoring_from_scratch=w0.bench(), precision=\'fp16\' if w0.nS is w0.n16 else \'fp32\')\n\n    # ---- latency model from real timings on this machine\n    sh.lat, cal = calibrate(w0, [False, True] if sh.allow_half else [False])\n    base_tps = 1000.0 / cal[\'fp32\'][\'ms\'][\'full\']\n    say(event=\'latency_model\', base_tok_s=round(base_tps, 2), **cal)\n\n    # ---- probe every part of the original model once: cost of removing it alone\n    t = time.time(); full = w0.nS.full(); jobs = []\n    for i in range(NL):\n        jobs.append(((\'attn\', i), full.apply((\'attn\', i)), i)); jobs.append(((\'mlp\', i), full.apply((\'mlp\', i)), i))\n        jobs.extend(((\'kv\', i, g), full.apply((\'kv\', i, g)), i) for g in range(nkv))\n        for wi in (1, 3, 5, 7):\n            a = full.copy(); a.w[i] = wi; jobs.append(((\'w\', i, wi), a, i))\n    res = {}\n    th = [threading.Thread(target=lambda w, js: res.update(w.probe(js)), args=(w, jobs[k::len(workers)])) for k, w in enumerate(workers)]\n    for x in th: x.start()\n    for x in th: x.join()\n    sh.p_attn = [res[(\'attn\', i)] for i in range(NL)]; sh.p_mlp = [res[(\'mlp\', i)] for i in range(NL)]\n    sh.p_kv = [[res[(\'kv\', i, g)] for g in range(nkv)] for i in range(NL)]\n    sh.p_w = []\n    for i in range(NL):\n        p = [0.0] * len(S.WIDTHS)\n        for wi in (1, 3, 5, 7): p[wi] = res[(\'w\', i, wi)]\n        for wi in (2, 4, 6): p[wi] = (p[wi - 1] + p[wi + 1]) / 2\n        sh.p_w.append(p)\n    pct = lambda v: round(100 * (math.exp(v) - 1), 2)\n    say(event=\'probe\', seconds=round(time.time() - t, 1), evals=len(jobs),\n        attn_removal_ppl_pct=[pct(v) for v in sh.p_attn], mlp_removal_ppl_pct=[pct(v) for v in sh.p_mlp],\n        mlp_width90_ppl_pct=[pct(p[1]) for p in sh.p_w], mlp_width50_ppl_pct=[pct(p[5]) for p in sh.p_w],\n        cheapest_kv_group_ppl_pct=[pct(min(v)) for v in sh.p_kv])\n\n    # ---- the agent\n    pol = Policy(); opt = torch.optim.Adam(pol.parameters(), lr=LR)\n    gens = [torch.Generator().manual_seed(SEED * 1000 + k) for k in range(len(workers))]\n    best = dict(S_pred=1.0, real=1.0, arch=None); gated = set()\n    buf_phi, buf_G = [], []; hist = []; elog = open(f\'{OUT}/episodes.jsonl\', \'w\'); n_ep = 0\n    say(event=\'agent\', policy_params=sum(p.numel() for p in pol.parameters()), edits_available=len(candidates(full, None, sh.allow_half, nkv)))\n\n    def gate(ep, tag):\n        """Whole search text, then validation, then real timing. Returns True if `ep` became the new best.\n        Candidates are ranked by the latency model (it has no noise); the real timing has to confirm it."""\n        nonlocal best\n        key = ep[\'arch\'].key() + (ep[\'arch\'].half,)\n        if key in gated or ep[\'S\'] <= best[\'S_pred\'] + 1e-4: return False\n        gated.add(key); pmd, pse = w0.pool_bound(ep[\'arch\'])\n        if not (math.isfinite(pmd) and pmd + pse <= BUDGET):\n            say(event=\'gate_fail\', check=\'whole search text\', where=tag, pred_speedup=round(ep[\'S\'], 4), bound=round(math.exp(pmd + pse), 4)); return False\n        v = w0.ratio(\'validation\', ep[\'arch\'])\n        if v[\'ratio\'] > TOL:\n            say(event=\'gate_fail\', check=\'validation\', where=tag, pred_speedup=round(ep[\'S\'], 4), val_ratio=round(v[\'ratio\'], 4)); return False\n        real = w0.tok_s(ep[\'arch\'], CAL_RUNS, CAL_TOKENS) / base_tps\n        if real < ep[\'S\'] * (1 - TIMING_TOL):\n            say(event=\'gate_fail\', check=\'real speed\', where=tag, pred_speedup=round(ep[\'S\'], 4), real_speedup=round(real, 4)); return False\n        best = dict(S_pred=ep[\'S\'], real=real, arch=ep[\'arch\'], val=v, search_bound=round(math.exp(pmd + pse), 4), edits=len(ep[\'acc\']))\n        json.dump(dict(pred_speedup=ep[\'S\'], real_speedup=real, **ep[\'arch\'].describe(nkv)), open(f\'{OUT}/best_arch.json\', \'w\'))\n        say(event=\'new_best\', where=tag, real_speedup=round(real, 4), pred_speedup=round(ep[\'S\'], 4), search_bound=best[\'search_bound\'],\n            val_ratio=round(v[\'ratio\'], 4), edits=len(ep[\'acc\']))\n        return True\n\n    def check(ep):\n        """The same checks, for reporting only (does not change the saved best)."""\n        pmd, pse = w0.pool_bound(ep[\'arch\']); v = w0.ratio(\'validation\', ep[\'arch\'])\n        ok = math.isfinite(pmd) and pmd + pse <= BUDGET and v[\'ratio\'] <= TOL\n        return dict(pred_speedup=round(ep[\'S\'], 4), edits=len(ep[\'acc\']), search_bound=round(math.exp(pmd + pse), 4), val_ratio=round(v[\'ratio\'], 4),\n                    passes=ok, real_speedup=round(w0.tok_s(ep[\'arch\'], CAL_RUNS, CAL_TOKENS) / base_tps, 4) if ok else None)\n\n    for w in workers: w.eval_s = w.busy_s = 0.0\n    t_loop = time.time(); rnd = 0; counter = [0]\n    while time.time() - t_loop < LOOP:\n        rnd += 1; snap = copy.deepcopy(pol); eps = run_round(workers, snap, gens, ROUND_EPISODES, counter)\n        trans = []\n        for ep in eps:\n            n_ep += 1; G_ = 0.0\n            for tr in reversed(ep[\'tr\']):\n                G_ += tr[\'r\']; tr[\'G\'] = G_\n            trans.extend(ep[\'tr\']); buf_phi.extend(tr[\'phi\'] for tr in ep[\'tr\']); buf_G.extend(tr[\'G\'] for tr in ep[\'tr\'])\n            hist.append(ep[\'S\'])\n            elog.write(json.dumps(dict(ep=n_ep, round=rnd, subset=ep[\'k\'], speedup=round(ep[\'S\'], 4), bound=round(math.exp(ep[\'md\'] + ep[\'se\']), 4),\n                                       accepted=ep[\'acc\'], refused=ep[\'rej\'])) + \'\\n\')\n        elog.flush()\n        if trans:\n            X = torch.tensor(buf_phi[-4000:]); y = torch.tensor(buf_G[-4000:])\n            wv = torch.linalg.solve(X.T @ X + 1e-2 * torch.eye(X.shape[1]), X.T @ y)\n            adv = torch.tensor([tr[\'G\'] for tr in trans]) - torch.tensor([tr[\'phi\'] for tr in trans]) @ wv\n            adv = (adv - adv.mean()) / (adv.std() + 1e-6)\n            for tr, a in zip(trans, adv): tr[\'adv\'] = a\n            update(pol, opt, trans)\n        for ep in sorted(eps, key=lambda e: -e[\'S\'])[:2]:\n            if gate(ep, f\'round {rnd}\'): break\n        el = time.time() - t_loop\n        say(event=\'round\', n=rnd, episodes=n_ep, mean_speedup=round(statistics.mean(e[\'S\'] for e in eps), 4),\n            max_speedup=round(max(e[\'S\'] for e in eps), 4), mean_edits=round(statistics.mean(len(e[\'acc\']) for e in eps), 1),\n            best_real=round(best[\'real\'], 4), evals_per_s=round(sh.evals / el, 1), memo_hits=sh.hits, loop_s=round(el, 1))\n    loop_s = time.time() - t_loop\n\n    # ---- after learning: what the trained network does on its own (no sampling), one run per search subset,\n    #      and a hand-written rule for reference (always take the edit with the best speed gained per budget spent)\n    g0 = torch.Generator().manual_seed(SEED); greedy, hand = [], []\n    for k in range(SUBSETS):\n        ep = w0.episode(pol, g0, k, greedy=True); greedy.append(check(ep)); gate(ep, f\'trained network, no sampling, subset {k}\')\n        hand.append(check(w0.episode(None, g0, k, chooser=lambda F: int(F[:, 17].argmax()))))\n    k = max(1, len(hist) // 10)\n    learn = dict(episodes=n_ep, rounds=rnd, loop_seconds=round(loop_s, 1), evals=sh.evals, memo_hits=sh.hits,\n                 worker_eval_seconds=[round(w.eval_s, 1) for w in workers], worker_busy_seconds=[round(w.busy_s, 1) for w in workers],\n                 first_tenth_mean_speedup=round(statistics.mean(hist[:k]), 4), last_tenth_mean_speedup=round(statistics.mean(hist[-k:]), 4),\n                 trained_network_no_sampling=greedy, hand_rule=hand)\n    say(event=\'learning\', **learn)\n    torch.save(pol.state_dict(), f\'{OUT}/policy.pt\')\n\n    # ---- final report on the saved best: unseen test text, real speed (alternating with the original), samples\n    rep = dict(learning=learn, baseline=dict(ppl=base_ppl, tok_s=base_tps), latency_model=cal, devices=devs)\n    if best[\'arch\'] is not None:\n        a = best[\'arch\']; fulla = w0.n32.full(); tb, ta = [], []\n        for _ in range(3):\n            tb.append(w0.tok_s(fulla, CAL_RUNS, CAL_TOKENS)); ta.append(w0.tok_s(a, CAL_RUNS, CAL_TOKENS))\n        tok = J.tokenizer(); M0 = S.materialize(w0.n32, fulla); M1 = S.materialize(w0.n32, a)\n        d0, d1 = G.Decoder(M0).capture(), G.Decoder(M1).capture(); samples = []\n        for pr in J.PROMPTS[:3]:\n            ids = tok(pr)[\'input_ids\']\n            samples.append(dict(prompt=pr, original=tok.decode(d0.generate(ids, 40)), edited=tok.decode(d1.generate(ids, 40))))\n        rep[\'best\'] = dict(architecture=a.describe(nkv), edits=best[\'edits\'],\n                           params=S.n_params(M1), params_original=S.n_params(M0),\n                           tok_s=round(statistics.median(ta), 2), tok_s_original=round(statistics.median(tb), 2),\n                           real_speedup=round(statistics.median(ta) / statistics.median(tb), 4), predicted_speedup=round(best[\'S_pred\'], 4),\n                           search_bound=best[\'search_bound\'], validation=w0.ratio(\'validation\', a), test=w0.ratio(\'test\', a),\n                           search=w0.ratio(\'search\', a), samples=samples)\n        say(event=\'final\', **{k: v for k, v in rep[\'best\'].items() if k not in (\'architecture\', \'samples\')})\n        say(event=\'architecture\', **{k: v for k, v in a.describe(nkv).items() if k not in (\'attn\', \'kv\', \'w\')})\n        for s_ in samples: say(event=\'sample\', **s_)\n    else:\n        say(event=\'final\', note=\'no architecture passed the validation gate and beat the original speed\')\n    json.dump(rep, open(f\'{OUT}/report.json\', \'w\'), indent=1)\n    say(event=\'done\')\n\n\nif __name__ == \'__main__\': main()\n', 'fused_test.py': '"""fused_test.py - on a GPU: is the fused integer-weight decoder exact, how fast is it, where does its time go,\nand what does each storage format cost in perplexity?"""\nimport json, math, time, traceback, torch\nimport cupy as cp\nimport judge as J, smol as S, fastgen as G, quant as Q, fused as F\n\ndef say(**k): print(json.dumps(k), flush=True)\ndev = \'cuda:0\'\nfrom transformers import AutoModelForCausalLM\nP = S.extract(AutoModelForCausalLM.from_pretrained(J.MODEL_DIR, dtype=torch.float32))\ntok = J.tokenizer(); prompt = tok(J.PROMPTS[0])[\'input_ids\']\nident = lambda net: net.set_rank([torch.arange(net.dff)] * net.NL)\nnet0 = S.Net(P, dev); ident(net0); ids = J.split(\'test\').to(dev); T = ids.shape[1]\nwith torch.no_grad(): base = net0.seq_nll(ids, net0.full())\nref = G.Decoder(S.materialize(net0, net0.full())).capture(); ref_tps = G.tok_per_s(ref, prompt)\nh = net0.full(); h.half = True; ref16 = G.Decoder(S.materialize(net0, h)).capture(); ref16_tps = G.tok_per_s(ref16, prompt)\nsay(event=\'reference\', gpu=torch.cuda.get_device_name(0), cupy=cp.__version__, torch_decoder_fp32_tok_s=round(ref_tps, 1), torch_decoder_fp16_tok_s=round(ref16_tps, 1),\n    test_ppl=round(math.exp(base.sum().item() / (base.numel() * (T - 1))), 3), text=tok.decode(ref.generate(prompt, 40)))\ndel ref, ref16\n\ndef check(name, fmt_of, rpb=4, breakdown=False):\n    """Quantize, compare the fused decoder with PyTorch running the same rounded weights, time it, measure perplexity."""\n    out = dict(event=\'fused\', model=name, rows_per_block=rpb if not callable(rpb) else \'tuned\', MB_per_token=round(Q.bytes_per_token(P, fmt_of) / 1e6, 1))\n    try:\n        arrs, Pq = Q.quantize_model(P, fmt_of, dev); netq = S.Net(Pq, dev); ident(netq)\n        with torch.no_grad():\n            d = (netq.seq_nll(ids, netq.full()) - base) / (T - 1)\n            x = netq.embed(torch.tensor([prompt], device=dev))\n            for i in range(netq.NL): x = netq.layer(i, x, netq.full())\n            ref_lg = netq.logits(x)[0, -1].float().cpu()\n        tdec = G.Decoder(S.materialize(netq, netq.full())).capture(); ttoks = tdec.generate(prompt, 64); del tdec, netq\n        out.update(test_ppl_change_pct=round(100 * (math.exp(d.mean().item()) - 1), 3), se_pct=round(100 * d.std().item() / math.sqrt(len(d)), 3))\n        dec = F.Fused(P, arrs, rpb=rpb)\n        lg = dec.first_logits(prompt); toks = dec.generate(prompt, 64); tps = dec.tok_per_s(prompt)\n        out.update(logits_max_rel_err=float((lg - ref_lg).abs().max() / ref_lg.abs().max()), tokens_same=f\'{sum(a == b for a, b in zip(toks, ttoks))}/64\',\n                   tok_s=round(tps, 1), ms_per_token=round(1000 / tps, 3), speedup_vs_torch_fp32=round(tps / ref_tps, 2), launches=len(dec.launches),\n                   text=tok.decode(toks[:40]))\n        if breakdown: out[\'ms_by_kernel\'] = dec.breakdown()\n        del dec\n    except Exception:\n        out[\'error\'] = traceback.format_exc()[-2500:]\n    cp.get_default_memory_pool().free_all_blocks(); torch.cuda.empty_cache()\n    say(**out)\n\ncheck(\'everything 16-bit\', lambda n: \'i16\', breakdown=True)\ncheck(\'everything 8-bit\', lambda n: \'i8\', breakdown=True)\ncheck(\'everything 4-bit\', lambda n: \'n4\', breakdown=True)\ncheck(\'8-bit, attention 4-bit\', lambda n: \'n4\' if n != \'E\' and n[1] in (\'q\', \'k\', \'v\', \'o\') else \'i8\')\ncheck(\'8-bit, MLP 4-bit\', lambda n: \'n4\' if n != \'E\' and n[1] in (\'g\', \'u\', \'dn\') else \'i8\')\nfor r in (1, 2, 8):\n    check(\'everything 8-bit\', lambda n: \'i8\', rpb=r)\nsay(event=\'done\')\n'}

